import{_ as e,o as i,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-03-29","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-03-29","date":"2023-03-29T00:00:00.000Z","updated":"2023-03-30T00:00:00.000Z","tags":["Ceph","RGW","性能计数器","配额管理","GitHub 2FA"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-03-29.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-03-29.md","lastUpdated":1780459816000}'),p={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-03-29.md"};function _(r,t,s,a,n,c){return i(),l("div",null,[...t[0]||(t[0]=[o("<p>本次会议主要讨论了以下几个议题：</p><ol><li><p><strong>用户配额的标记性能计数器</strong>：</p><ul><li>讨论了在Prometheus中监控每个RGW用户的配额分配和使用情况的需求。</li><li>决定实现一个缓存机制来处理用户配额的频繁更新，并添加用户标签到前端计数器。</li><li>由Ellie负责实现缓存机制，并添加用户标签，同时进行测试以验证系统的可扩展性。</li></ul></li><li><p><strong>GitHub组织的两因素认证要求</strong>：</p><ul><li>讨论了GitHub组织即将实施的两因素认证要求，以及未启用2FA的成员将被移除的问题。</li><li>决定提醒所有成员尽快启用2FA，以避免失去对GitHub组织的访问权限。</li></ul></li><li><p><strong>日志数据与桶策略的交互</strong>：</p><ul><li>讨论了如何禁用区域的日志记录，特别是与桶策略相关的日志记录。</li><li>决定使用<code>supports_data_export</code>和<code>supports_data_import</code>来替代区域范围的标志。</li><li>由Emil负责研究如何调整初始化顺序以解决依赖问题，并更新相关的PR。</li></ul></li><li><p><strong>其他讨论</strong>：</p><ul><li>会议还讨论了同步模块和多站点配置的一般问题。</li></ul></li></ol><p>会议在讨论完所有议题后结束，感谢所有参与者的贡献。</p>",3)])])}const u=e(p,[["render",_]]);export{g as __pageData,u as default};
